var scene=UnityEditor.SceneManagement.EditorSceneManager.GetActiveScene(); var old=UnityEngine.GameObject.Find("BuildingTilemap"); var root=UnityEngine.GameObject.Find("BuildingVisuals"); var tm=old.GetComponent<UnityEngine.Tilemaps.Tilemap>(); var tr=old.GetComponent<UnityEngine.Tilemaps.TilemapRenderer>(); var coll=UnityEngine.GameObject.Find("CollisionTilemap"); var c1=coll==null?null:coll.GetComponent<UnityEngine.Tilemaps.TilemapCollider2D>(); var c2=coll==null?null:coll.GetComponent<UnityEngine.CompositeCollider2D>(); int n=0;foreach(var p in tm.cellBounds.allPositionsWithin)if(tm.GetTile(p)!=null)n++; int children=root==null?0:root.transform.childCount; return new {scene=scene.path,buildingTiles=n,buildingRendererEnabled=tr==null?false:tr.enabled,buildingVisualChildren=children,collisionTilemapColliderEnabled=c1==null?false:c1.enabled,collisionCompositeEnabled=c2==null?false:c2.enabled};
